// Offer generated bytes or text as a download through a Blob anchor (the only form the parity harness captures).
// $lib/components/csv.ts download() takes a string only; DOCX needs bytes.
export function downloadBlob(name: string, content: string | Uint8Array, type: string) {
	const url = URL.createObjectURL(new Blob([content as BlobPart], { type }));
	const a = document.createElement('a');
	a.href = url;
	a.download = name;
	document.body.append(a);
	a.click();
	a.remove();
	setTimeout(() => URL.revokeObjectURL(url), 1000);
}

/** v5's attribute escape A() (& < > "), applied to every value written into generated HTML (S-discovery_tab-4). */
export const attr = (s: unknown) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
